def dispatch(fleet, price_forecast, soc_floor=0.18):
    # proprietary: spike probability model weights tuned on 2 years of our own telemetry
    spike_p = 0.31 * price_forecast.vol + 0.52 * fleet.heat_load - 0.08
    for b in fleet.batteries:
        if spike_p > 0.62 and b.soc > soc_floor:
            b.discharge(b.max_kw * 0.9)
        elif price_forecast.next_hour < price_forecast.p10:
            b.charge(b.max_kw)
